// IPTV Web Player — browse this fork's playlists and play them in the browser.
// Vanilla ES modules, no build step. Data comes from ./data/, generated by
// web/scripts/build-index.mjs.

const HLS_JS = 'https://cdn.jsdelivr.net/npm/hls.js@1.7.4/dist/hls.min.js'
const DASH_JS = 'https://cdn.jsdelivr.net/npm/dashjs@5.3.0/dist/modern/umd/dash.all.min.js'
const STORE_KEY = 'iptv-web-player'

// ---------------------------------------------------------------- settings

const defaults = {
  proxy: '/proxy',
  directFirst: true,
  showNsfw: false,
  autoNext: true,
  favourites: [],
  lastCountry: null,
  language: 'tam',
  provider: null,
  theme: 'system'
}

function loadStore() {
  try {
    return { ...defaults, ...JSON.parse(localStorage.getItem(STORE_KEY) || '{}') }
  } catch {
    return { ...defaults }
  }
}

function saveStore() {
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(settings))
  } catch {
    /* private browsing, blocked storage — settings just won't persist */
  }
}

const settings = loadStore()
const favourites = new Set(settings.favourites)

// ------------------------------------------------------------------- state

const state = {
  meta: null,
  view: {
    kind: 'country', country: null,
    category: null, language: null, provider: null,
    query: ''
  },
  channels: [],
  searchIndex: null,
  current: null,
  sourceIndex: 0,
  failed: new Set(),
  // Snapshot of the list the player is walking, taken when it opens so that a
  // later filter change cannot shift next/previous under the viewer.
  playlist: [],
  playlistIndex: -1
}

const countryCache = new Map()
const el = id => document.getElementById(id)

const dom = {
  navToggle: el('navToggle'), sidebar: el('sidebar'),
  search: el('search'), favouritesBtn: el('favouritesBtn'), favCount: el('favCount'),
  categoryChips: el('categoryChips'), categoryMore: el('categoryMore'),
  themeBtn: el('themeBtn'), countryList: el('countryList'),
  countryFilter: el('countryFilter'), countryTotal: el('countryTotal'),
  languageSelect: el('languageSelect'), languageTotal: el('languageTotal'),
  providerSelect: el('providerSelect'), providerTotal: el('providerTotal'),
  viewTitle: el('viewTitle'), viewSub: el('viewSub'),
  grid: el('channels'), emptyState: el('emptyState'), emptyBody: el('emptyBody'),
  clearFilters: el('clearFilters'),
  footStats: el('footStats'), footGenerated: el('footGenerated'),
  backdrop: el('playerBackdrop'), player: el('player'),
  playerLogo: el('playerLogo'), playerTitle: el('playerTitle'), playerMeta: el('playerMeta'),
  playerFav: el('playerFav'), playerClose: el('playerClose'), playerNote: el('playerNote'),
  playerBack: el('playerBack'), playerPrev: el('playerPrev'), playerNext: el('playerNext'),
  playerPos: el('playerPos'),
  video: el('video'), videoStatus: el('videoStatus'), videoStatusText: el('videoStatusText'),
  videoStatusHint: el('videoStatusHint'), videoRetry: el('videoRetry'), sourceRow: el('sourceRow'),
  settingsBtn: el('settingsBtn'), settingsSheet: el('settingsSheet'), settingsClose: el('settingsClose'),
  proxyInput: el('proxyInput'), directFirst: el('directFirst'),
  showNsfw: el('showNsfw'), autoNext: el('autoNext'),
  toast: el('toast')
}

// ------------------------------------------------------------------- utils

let toastTimer
function toast(message, ms = 3200) {
  dom.toast.textContent = message
  dom.toast.hidden = false
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => { dom.toast.hidden = true }, ms)
}

function b64url(value) {
  const bytes = new TextEncoder().encode(value)
  let binary = ''
  for (const byte of bytes) binary += String.fromCharCode(byte)
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

// Builds the proxied URL for a stream, carrying the headers the stream needs.
function proxyUrl(stream) {
  const base = (settings.proxy || '/proxy').replace(/\/+$/, '') || '/proxy'
  const params = new URLSearchParams({ u: b64url(stream.url) })
  if (stream.userAgent) params.set('ua', b64url(stream.userAgent))
  if (stream.referrer) params.set('r', b64url(stream.referrer))
  return `${base}?${params.toString()}`
}

// A stream can only be attempted directly when the browser is allowed to make
// the request at all: https on an https page, and no forbidden headers needed.
function canTryDirect(stream) {
  if (stream.userAgent || stream.referrer) return false
  if (location.protocol === 'https:' && stream.url.startsWith('http://')) return false
  return true
}

function loadScript(src) {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) return resolve()
    const tag = document.createElement('script')
    tag.src = src
    tag.onload = () => resolve()
    tag.onerror = () => reject(new Error(`Failed to load ${src}`))
    document.head.appendChild(tag)
  })
}

async function getJSON(path) {
  const res = await fetch(path)
  if (!res.ok) throw new Error(`${path} -> HTTP ${res.status}`)
  return res.json()
}

function matchesFilters(channel) {
  if (channel.nsfw && !settings.showNsfw) return false
  if (state.view.category && !channel.categories.includes(state.view.category)) return false
  if (state.view.language && !channel.languages.includes(state.view.language)) return false
  if (state.view.provider && !(channel.providers || []).includes(state.view.provider)) return false
  return true
}

// One human-readable summary of whatever filters are currently applied.
function activeFilterLabel() {
  const parts = []
  if (state.view.category) {
    const category = state.meta.categories.find(c => c.id === state.view.category)
    parts.push(category?.name || state.view.category)
  }
  if (state.view.language) {
    const language = state.meta.languages.find(l => l.code === state.view.language)
    parts.push(language?.name || state.view.language)
  }
  if (state.view.provider) {
    const provider = (state.meta.providers || []).find(p => p.id === state.view.provider)
    parts.push(provider?.name || state.view.provider)
  }
  return parts.join(' + ')
}

const nonWord = /[^\p{L}\p{N}]+/gu
const normalise = text => text.toLowerCase().replace(nonWord, ' ').trim()

// Stable hue per channel name, so logo-less tiles are distinguishable from each
// other and keep the same colour across reloads.
function monoHue(name) {
  let hash = 0
  for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) % 360
  // Constrained to 190-300deg (cyan through violet) so the tiles stay in family
  // with the slate/blue palette instead of drifting into muddy olives.
  return 190 + (hash % 111)
}

const THEME_ICONS = {
  system: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2.5" y="4" width="19" height="13" rx="2"/><path d="M8 20h8M12 17v3"/></svg>',
  light: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2.5M12 19.5V22M22 12h-2.5M4.5 12H2M19.07 4.93l-1.77 1.77M6.7 17.3l-1.77 1.77M19.07 19.07l-1.77-1.77M6.7 6.7L4.93 4.93"/></svg>',
  dark: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 14.2A8.2 8.2 0 1 1 9.8 4a6.6 6.6 0 0 0 10.2 10.2z"/></svg>'
}
const THEME_LABELS = { system: 'follow system', light: 'light', dark: 'dark' }

function applyTheme(theme) {
  if (theme === 'system') document.documentElement.removeAttribute('data-theme')
  else document.documentElement.setAttribute('data-theme', theme)
  if (dom.themeBtn) {
    dom.themeBtn.innerHTML = THEME_ICONS[theme] || THEME_ICONS.system
    const label = `Theme: ${THEME_LABELS[theme] || 'follow system'}`
    dom.themeBtn.setAttribute('aria-label', label)
    dom.themeBtn.title = `${label} — click to change`
  }
}

// ------------------------------------------------------------------- data

async function loadCountry(code) {
  const key = code.toLowerCase()
  if (countryCache.has(key)) return countryCache.get(key)
  const promise = getJSON(`./data/channels/${key}.json`)
    .then(payload => payload.channels)
    .catch(err => {
      countryCache.delete(key)
      throw err
    })
  countryCache.set(key, promise)
  return promise
}

async function loadSearchIndex() {
  if (!state.searchIndex) state.searchIndex = await getJSON('./data/search.json')
  return state.searchIndex
}

// Favourites are stored as "CC/channelId" so a channel can be resolved back to
// the country shard that holds it.
const favKey = channel => `${channel.country}/${channel.id}`

function toggleFavourite(channel) {
  const key = favKey(channel)
  if (favourites.has(key)) favourites.delete(key)
  else favourites.add(key)
  settings.favourites = [...favourites]
  saveStore()
  renderFavCount()
  return favourites.has(key)
}

function renderFavCount() {
  dom.favCount.textContent = String(favourites.size)
}

// ---------------------------------------------------------------- rendering

const CHUNK = 120
let renderCursor = 0
let renderQueue = []
let observer = null
let ambiguousNames = new Set()

function channelCard(channel) {
  const card = document.createElement('button')
  card.className = 'card'
  card.type = 'button'
  card.setAttribute('role', 'listitem')
  card.dataset.id = channel.id

  const thumb = document.createElement('div')
  thumb.className = 'card-thumb'
  const useMonogram = () => {
    thumb.style.setProperty('--mono', String(monoHue(channel.name)))
    thumb.append(initial(channel.name))
  }
  if (channel.logo) {
    const img = document.createElement('img')
    img.src = channel.logo
    img.alt = ''
    img.loading = 'lazy'
    img.decoding = 'async'
    // ~6% of the logo URLs in the database are dead; fall back to a monogram.
    img.onerror = () => {
      img.remove()
      useMonogram()
    }
    thumb.append(img)
  } else {
    useMonogram()
  }

  const name = document.createElement('div')
  name.className = 'card-name'
  name.textContent = channel.name

  const tags = document.createElement('div')
  tags.className = 'card-tags'
  const best = channel.streams.find(s => s.quality)
  if (best) {
    const quality = document.createElement('span')
    quality.className = 'tag tag-quality'
    quality.textContent = best.quality
    tags.append(quality)
  }
  // 'SD' covers two thirds of all channels, so a feed badge everywhere would be
  // noise. Show it only where the same name appears more than once here.
  if (channel.feed && ambiguousNames.has(channel.name)) {
    const feed = document.createElement('span')
    feed.className = 'tag tag-feed'
    feed.textContent = channel.feed
    tags.append(feed)
  }

  const count = document.createElement('span')
  count.className = 'tag'
  count.textContent = `${channel.streams.length} src`
  tags.append(count)
  if (channel.nsfw) {
    const nsfw = document.createElement('span')
    nsfw.className = 'tag tag-nsfw'
    nsfw.textContent = '18+'
    tags.append(nsfw)
  }

  const fav = document.createElement('button')
  fav.className = 'card-fav'
  fav.type = 'button'
  fav.textContent = '★'
  fav.setAttribute('aria-label', `Favourite ${channel.name}`)
  fav.setAttribute('aria-pressed', String(favourites.has(favKey(channel))))
  fav.addEventListener('click', event => {
    event.stopPropagation()
    fav.setAttribute('aria-pressed', String(toggleFavourite(channel)))
  })

  card.append(thumb, name, tags, fav)
  card.addEventListener('click', () => openPlayer(channel))
  return card
}

function initial(name) {
  const span = document.createElement('span')
  span.className = 'card-initial'
  span.textContent = (name.match(/\p{L}|\p{N}/u)?.[0] || '?').toUpperCase()
  return span
}

function renderChunk() {
  const slice = renderQueue.slice(renderCursor, renderCursor + CHUNK)
  if (!slice.length) return
  const fragment = document.createDocumentFragment()
  for (const channel of slice) fragment.append(channelCard(channel))
  dom.grid.append(fragment)
  renderCursor += slice.length
  if (renderCursor < renderQueue.length) addSentinel()
}

function addSentinel() {
  observer?.disconnect()
  const sentinel = document.createElement('div')
  sentinel.style.cssText = 'grid-column:1/-1;height:1px'
  dom.grid.append(sentinel)
  observer = new IntersectionObserver(entries => {
    if (!entries.some(e => e.isIntersecting)) return
    observer.disconnect()
    sentinel.remove()
    renderChunk()
  }, { rootMargin: '600px' })
  observer.observe(sentinel)
}

function renderChannels(channels, { title, subtitle, emptyMessage }) {
  observer?.disconnect()
  dom.grid.replaceChildren()
  dom.grid.setAttribute('aria-busy', 'false')
  dom.viewTitle.textContent = title
  dom.viewSub.textContent = subtitle
  renderQueue = channels
  renderCursor = 0

  const seen = new Map()
  for (const channel of channels) seen.set(channel.name, (seen.get(channel.name) || 0) + 1)
  ambiguousNames = new Set([...seen].filter(([, n]) => n > 1).map(([name]) => name))

  if (!channels.length) {
    dom.emptyState.hidden = false
    dom.emptyBody.textContent = emptyMessage || 'Try a different country or search term.'
    dom.clearFilters.hidden = !activeFilterLabel()
    return
  }
  dom.emptyState.hidden = true
  dom.clearFilters.hidden = true
  renderChunk()
}

function renderSidebar() {
  const { countries, categories } = state.meta
  dom.countryTotal.textContent = `(${countries.length})`

  const COLLAPSED_CHIPS = 8
  dom.categoryChips.replaceChildren()
  categories.forEach((category, index) => {
    const chip = document.createElement('button')
    chip.className = 'chip'
    chip.type = 'button'
    chip.textContent = category.name
    chip.setAttribute('aria-pressed', 'false')
    chip.dataset.category = category.id
    if (index >= COLLAPSED_CHIPS) chip.dataset.overflow = 'true'
    chip.title = `${category.count} channels`
    chip.addEventListener('click', () => {
      state.view.category = state.view.category === category.id ? null : category.id
      syncChips()
      refreshView()
    })
    dom.categoryChips.append(chip)
  })
  dom.categoryMore.hidden = categories.length <= COLLAPSED_CHIPS
  dom.categoryMore.textContent = `Show all ${categories.length}`

  const languages = state.meta.languages || []
  dom.languageTotal.textContent = `(${languages.length})`
  const options = [new Option('All languages', '')]
  for (const language of languages) {
    options.push(new Option(`${language.name} (${language.count})`, language.code))
  }
  dom.languageSelect.replaceChildren(...options)
  dom.languageSelect.value = state.view.language || ''

  const providers = state.meta.providers || []
  dom.providerTotal.textContent = `(${providers.length})`
  const providerOptions = [new Option('All providers', '')]
  for (const provider of providers) {
    providerOptions.push(new Option(`${provider.name} (${provider.count})`, provider.id))
  }
  dom.providerSelect.replaceChildren(...providerOptions)
  dom.providerSelect.value = state.view.provider || ''

  renderCountryList('')
}

function syncChips() {
  for (const chip of dom.categoryChips.children) {
    const active = chip.dataset.category === state.view.category
    chip.setAttribute('aria-pressed', String(active))
    // A selected category must stay visible even while the list is collapsed.
    if (active) delete chip.dataset.overflow
  }
}

function renderCountryList(filter) {
  const needle = normalise(filter)
  dom.countryList.replaceChildren()
  for (const country of state.meta.countries) {
    if (needle && !normalise(country.name).includes(needle) && !normalise(country.code).includes(needle)) continue
    const item = document.createElement('li')
    const button = document.createElement('button')
    button.className = 'country-btn'
    button.type = 'button'
    button.dataset.code = country.code
    button.setAttribute('aria-current', String(country.code === state.view.country && state.view.kind === 'country'))
    button.innerHTML =
      `<span class="country-flag">${country.flag}</span>` +
      `<span class="country-name"></span>` +
      `<span class="country-num">${country.count}</span>`
    button.querySelector('.country-name').textContent = country.name
    button.addEventListener('click', () => {
      location.hash = `#/country/${country.code.toLowerCase()}`
      if (window.matchMedia('(max-width: 860px)').matches) setNav(false)
    })
    item.append(button)
    dom.countryList.append(item)
  }
}

function syncCountrySelection() {
  for (const item of dom.countryList.children) {
    const button = item.firstElementChild
    button.setAttribute(
      'aria-current',
      String(state.view.kind === 'country' && button.dataset.code === state.view.country)
    )
  }
}

// ------------------------------------------------------------------- views

async function showCountry(code) {
  state.view = { ...state.view, kind: 'country', country: code, query: '' }
  if (dom.search.value.trim().length < 2) dom.search.value = ''
  dom.favouritesBtn.setAttribute('aria-pressed', 'false')
  syncCountrySelection()
  const info = state.meta.countries.find(c => c.code === code)
  dom.viewTitle.textContent = info ? `${info.flag} ${info.name}` : code
  dom.viewSub.textContent = 'Loading channels…'
  dom.grid.setAttribute('aria-busy', 'true')

  try {
    state.channels = await loadCountry(code)
  } catch {
    renderChannels([], {
      title: info ? `${info.flag} ${info.name}` : code,
      subtitle: '',
      emptyMessage: `Could not load channel data for ${code}.`
    })
    return
  }
  if (state.view.country !== code) return // user navigated away mid-load

  settings.lastCountry = code
  saveStore()

  const visible = state.channels.filter(matchesFilters)
  const streams = visible.reduce((n, c) => n + c.streams.length, 0)
  renderChannels(visible, {
    title: info ? `${info.flag} ${info.name}` : code,
    subtitle: `${visible.length.toLocaleString()} channels · ${streams.toLocaleString()} sources${
      activeFilterLabel() ? ` · ${activeFilterLabel()}` : ''
    }`,
    emptyMessage: activeFilterLabel()
      ? `No channels in this country match ${activeFilterLabel()}.`
      : 'This country has no channels in the playlists.'
  })
}

async function showFavourites() {
  state.view = { ...state.view, kind: 'favourites', query: '' }
  dom.favouritesBtn.setAttribute('aria-pressed', 'true')
  syncCountrySelection()
  dom.grid.setAttribute('aria-busy', 'true')
  dom.viewTitle.textContent = '★ Favourites'
  dom.viewSub.textContent = 'Loading…'

  const byCountry = new Map()
  for (const key of favourites) {
    const [country, ...rest] = key.split('/')
    if (!byCountry.has(country)) byCountry.set(country, new Set())
    byCountry.get(country).add(rest.join('/'))
  }

  const found = []
  await Promise.all(
    [...byCountry.entries()].map(async ([country, ids]) => {
      try {
        const channels = await loadCountry(country)
        for (const channel of channels) if (ids.has(channel.id)) found.push(channel)
      } catch {
        /* a stale favourite pointing at a country that no longer exists */
      }
    })
  )
  if (state.view.kind !== 'favourites') return

  found.sort((a, b) => a.name.localeCompare(b.name))
  const visible = found.filter(matchesFilters)
  renderChannels(visible, {
    title: '★ Favourites',
    subtitle: `${visible.length.toLocaleString()} channels`,
    emptyMessage: 'Star a channel from any grid and it will show up here.'
  })
}

let searchToken = 0
async function showSearch(query) {
  const token = ++searchToken
  state.view = { ...state.view, kind: 'search', query }
  dom.favouritesBtn.setAttribute('aria-pressed', 'false')
  syncCountrySelection()
  dom.grid.setAttribute('aria-busy', 'true')
  dom.viewTitle.textContent = `Search: ${query}`
  dom.viewSub.textContent = 'Searching…'

  const index = await loadSearchIndex()
  if (token !== searchToken) return

  const needle = normalise(query)
  const terms = needle.split(' ').filter(Boolean)
  const hits = []
  for (const row of index) {
    const [, name, country, nsfw] = row
    if (nsfw && !settings.showNsfw) continue
    const haystack = normalise(name)
    if (!terms.every(term => haystack.includes(term))) continue
    // Exact prefix matches float to the top.
    hits.push({ row, score: haystack.startsWith(needle) ? 0 : haystack.indexOf(terms[0]) })
    if (hits.length >= 400) break
  }
  hits.sort((a, b) => a.score - b.score || a.row[1].localeCompare(b.row[1]))

  const needed = new Set(hits.map(h => h.row[2]))
  const shards = new Map()
  await Promise.all(
    [...needed].map(async code => {
      try {
        shards.set(code, await loadCountry(code))
      } catch {
        /* skip unreachable shard */
      }
    })
  )
  if (token !== searchToken) return

  const resolved = []
  for (const { row } of hits) {
    const [id, , country] = row
    const channel = shards.get(country)?.find(c => c.id === id)
    if (channel && matchesFilters(channel)) resolved.push(channel)
  }

  renderChannels(resolved, {
    title: `Search: ${query}`,
    subtitle: `${resolved.length.toLocaleString()} matches${hits.length >= 400 ? ' (showing first 400)' : ''}`,
    emptyMessage: `No channel names match “${query}”.`
  })
}

function refreshView() {
  const { kind, country, query } = state.view
  if (kind === 'search' && query) return showSearch(query)
  if (kind === 'favourites') return showFavourites()
  if (country) return showCountry(country)
}

// ----------------------------------------------------------------- routing

function route() {
  const hash = location.hash.replace(/^#\/?/, '')
  const [section, value] = hash.split('/')

  if (section === 'search' && value) {
    const query = decodeURIComponent(value)
    if (dom.search.value !== query) dom.search.value = query
    return showSearch(query)
  }
  if (section === 'favourites') return showFavourites()
  if (section === 'country' && value) return showCountry(value.toUpperCase())

  // Default view. Alphabetical order would land on Afghanistan and its 15
  // channels, which reads as a broken page, so prefer where the user last was,
  // then India (the largest playlist in this repo), then whatever is biggest.
  const byCode = code => state.meta.countries.find(c => c.code === code && c.count > 0)
  const biggest = [...state.meta.countries].sort((a, b) => b.count - a.count)[0]
  const fallback = byCode(settings.lastCountry) || byCode('IN') || biggest
  if (fallback) return showCountry(fallback.code)
}

// ------------------------------------------------------------------ player

let engine = null
let playToken = 0
let mediaRecoveryUsed = false

function setStatus(stateName, text, hint = '', retry = false) {
  dom.videoStatus.hidden = stateName === 'playing'
  dom.videoStatus.dataset.state = stateName
  dom.videoStatusText.textContent = text
  dom.videoStatusHint.textContent = hint
  dom.videoRetry.hidden = !retry
}

function stopPlayback() {
  playToken++
  if (engine) {
    try { engine.destroy() } catch { /* engine already torn down */ }
    engine = null
  }
  const video = dom.video
  try {
    video.pause()
    video.removeAttribute('src')
    video.load()
  } catch { /* nothing loaded yet */ }
}

// Which transport to try first for a given stream.
function firstMode(stream) {
  return settings.directFirst && canTryDirect(stream) && settings.proxy ? 'direct' : 'proxy'
}

function nextUntried(from) {
  const streams = state.current?.streams || []
  for (let i = from + 1; i < streams.length; i++) if (!state.failed.has(i)) return i
  for (let i = 0; i < from; i++) if (!state.failed.has(i)) return i
  return -1
}

async function attempt(index, mode) {
  stopPlayback()
  const token = playToken
  const channel = state.current
  if (!channel) return
  const stream = channel.streams[index]
  if (!stream) return

  state.sourceIndex = index
  mediaRecoveryUsed = false
  renderSources()

  const viaProxy = mode === 'proxy'
  if (viaProxy && !settings.proxy) {
    setStatus('error', 'No proxy configured',
      'This stream needs a proxy (it is http-only, needs a custom User-Agent, or its server blocks cross-origin requests). Set a proxy URL in Settings.')
    return
  }
  const url = viaProxy ? proxyUrl(stream) : stream.url

  setStatus(
    'loading',
    viaProxy ? 'Connecting via proxy…' : 'Connecting…',
    `Source ${index + 1} of ${channel.streams.length}${stream.quality ? ` · ${stream.quality}` : ''}`
  )

  const fail = reason => {
    if (token !== playToken) return
    // Resilience ladder: direct -> proxy -> this channel's next source.
    if (!viaProxy && settings.proxy) {
      attempt(index, 'proxy')
      return
    }
    state.failed.add(index)
    renderSources()
    if (settings.autoNext) {
      const next = nextUntried(index)
      if (next !== -1) {
        attempt(next, firstMode(channel.streams[next]))
        return
      }
    }
    setStatus('error', 'Could not play this channel',
      reason || 'Every source for this channel failed. These are public streams and many go offline without notice.',
      nextUntried(index) !== -1)
  }

  const succeed = () => {
    if (token !== playToken) return
    setStatus('playing', '')
  }

  try {
    if (stream.kind === 'dash') {
      await loadScript(DASH_JS)
      if (token !== playToken) return
      const player = window.dashjs.MediaPlayer().create()
      player.updateSettings({ streaming: { retryAttempts: { MPD: 1 } } })
      player.on(window.dashjs.MediaPlayer.events.ERROR, () => fail('The DASH manifest could not be loaded.'))
      player.on(window.dashjs.MediaPlayer.events.PLAYBACK_PLAYING, succeed)
      player.initialize(dom.video, url, true)
      engine = { destroy: () => player.destroy() }
      return
    }

    if (stream.kind === 'file') {
      dom.video.src = url
      dom.video.onerror = () => fail('The media file could not be loaded.')
      dom.video.onplaying = succeed
      engine = { destroy: () => { dom.video.onerror = null; dom.video.onplaying = null } }
      return
    }

    // HLS
    await loadScript(HLS_JS)
    if (token !== playToken) return
    const Hls = window.Hls

    if (Hls?.isSupported()) {
      const hls = new Hls({
        enableWorker: true,
        backBufferLength: 30,
        manifestLoadingTimeOut: 15000,
        manifestLoadingMaxRetry: 1,
        levelLoadingMaxRetry: 2,
        fragLoadingMaxRetry: 2
      })
      hls.on(Hls.Events.ERROR, (_event, data) => {
        if (!data.fatal) return
        if (data.type === Hls.ErrorTypes.MEDIA_ERROR && !mediaRecoveryUsed) {
          mediaRecoveryUsed = true
          hls.recoverMediaError()
          return
        }
        if (data.type === Hls.ErrorTypes.NETWORK_ERROR) {
          fail(
            viaProxy
              ? 'The stream server did not respond, or the channel is offline.'
              : 'Blocked by the browser or unreachable — retrying through the proxy.'
          )
          return
        }
        fail('The stream could not be decoded.')
      })
      hls.on(Hls.Events.FRAG_BUFFERED, succeed)
      hls.loadSource(url)
      hls.attachMedia(dom.video)
      engine = { destroy: () => hls.destroy() }
      return
    }

    if (dom.video.canPlayType('application/vnd.apple.mpegurl')) {
      // Safari plays HLS natively; hls.js is unsupported there on iOS.
      dom.video.src = url
      dom.video.onerror = () => fail('Safari could not open this stream.')
      dom.video.onplaying = succeed
      engine = { destroy: () => { dom.video.onerror = null; dom.video.onplaying = null } }
      return
    }

    setStatus('error', 'HLS is not supported in this browser', 'Try Chrome, Edge, Firefox or Safari.')
  } catch (err) {
    fail(`Player failed to start: ${err?.message || 'unknown error'}`)
  }
}

function renderSources() {
  const channel = state.current
  if (!channel) return
  dom.sourceRow.replaceChildren()

  channel.streams.forEach((stream, index) => {
    const button = document.createElement('button')
    button.className = 'source-btn'
    button.type = 'button'
    button.setAttribute('aria-pressed', String(index === state.sourceIndex))
    button.dataset.failed = String(state.failed.has(index))

    const dot = document.createElement('span')
    dot.className = 'source-dot'
    const label = document.createElement('span')
    const bits = [stream.quality || `Source ${index + 1}`]
    if (stream.kind !== 'hls') bits.push(stream.kind.toUpperCase())
    if (!canTryDirect(stream)) bits.push('proxy')
    if (stream.partTime) bits.push('not 24/7')
    label.textContent = bits.join(' · ')

    button.title = stream.url
    button.append(dot, label)
    button.addEventListener('click', () => {
      state.failed.delete(index)
      attempt(index, firstMode(stream))
    })
    dom.sourceRow.append(button)
  })

  const stream = channel.streams[state.sourceIndex]
  const needsProxy = channel.streams.filter(s => !canTryDirect(s)).length
  dom.playerNote.textContent = stream
    ? `${needsProxy} of ${channel.streams.length} sources need the proxy up front (http-only or custom headers). ` +
      'Others may still fall back to it if the server refuses cross-origin requests.'
    : ''
}

function openPlayer(channel, { keepHistory = false } = {}) {
  // Walking the visible, filtered list is what makes next/previous feel right:
  // on India + Tamil you surf 117 channels, not all 13,434.
  const index = renderQueue.indexOf(channel)
  if (index !== -1) {
    state.playlist = renderQueue
    state.playlistIndex = index
  } else if (state.playlistIndex === -1) {
    state.playlist = [channel]
    state.playlistIndex = 0
  }

  // One history entry for the whole viewing session, so the device/browser back
  // button closes the player instead of leaving the site.
  if (!keepHistory && dom.backdrop.hidden) {
    history.pushState({ iptvPlayer: true }, '')
  }

  state.current = channel
  state.failed = new Set()
  state.sourceIndex = 0

  dom.playerTitle.textContent = channel.name
  const country = state.meta.countries.find(c => c.code === channel.country)
  dom.playerMeta.textContent = [
    country ? `${country.flag} ${country.name}` : channel.country,
    channel.categories.join(', ') || null,
    channel.feed ? `feed ${channel.feed}` : null
  ].filter(Boolean).join(' · ')

  if (channel.logo) {
    dom.playerLogo.src = channel.logo
    dom.playerLogo.hidden = false
    dom.playerLogo.onerror = () => { dom.playerLogo.hidden = true }
  } else {
    dom.playerLogo.hidden = true
  }

  dom.playerFav.setAttribute('aria-pressed', String(favourites.has(favKey(channel))))
  renderPlayerNav()
  dom.backdrop.hidden = false
  document.body.style.overflow = 'hidden'
  dom.playerClose.focus()

  attempt(0, firstMode(channel.streams[0]))
}

function renderPlayerNav() {
  const total = state.playlist.length
  const canStep = total > 1
  dom.playerPrev.disabled = !canStep
  dom.playerNext.disabled = !canStep
  dom.playerPos.textContent = canStep ? `${state.playlistIndex + 1} / ${total}` : ''
}

// Wraps around, so surfing never dead-ends at the edge of the list.
function stepChannel(delta) {
  const total = state.playlist.length
  if (total < 2) return
  state.playlistIndex = (state.playlistIndex + delta + total) % total
  const next = state.playlist[state.playlistIndex]
  if (next) openPlayer(next, { keepHistory: true })
}

function closePlayer({ fromHistory = false } = {}) {
  if (dom.backdrop.hidden) return
  stopPlayback()
  state.current = null
  state.playlist = []
  state.playlistIndex = -1
  dom.backdrop.hidden = true
  document.body.style.overflow = ''
  setStatus('loading', 'Connecting…')
  // Drop the entry pushed on open, unless the browser already popped it.
  if (!fromHistory && history.state?.iptvPlayer) history.back()
}

// ------------------------------------------------------------------ events

function setNav(open) {
  dom.sidebar.dataset.open = String(open)
  dom.navToggle.setAttribute('aria-expanded', String(open))
}

function openSettings(open) {
  dom.settingsSheet.hidden = !open
  dom.settingsBtn.setAttribute('aria-expanded', String(open))
  if (open) dom.proxyInput.focus()
}

function bindEvents() {
  dom.navToggle.addEventListener('click', () => setNav(dom.sidebar.dataset.open !== 'true'))

  let searchTimer
  dom.search.addEventListener('input', () => {
    clearTimeout(searchTimer)
    const query = dom.search.value.trim()
    searchTimer = setTimeout(() => {
      if (query.length < 2) {
        if (state.view.kind === 'search') backToBrowsing()
        return
      }
      location.hash = `#/search/${encodeURIComponent(query)}`
    }, 260)
  })

  function backToBrowsing() {
    const code = state.view.country || state.meta.countries.find(c => c.count > 0)?.code
    if (code) location.hash = `#/country/${code.toLowerCase()}`
  }

  dom.favouritesBtn.addEventListener('click', () => {
    if (state.view.kind === 'favourites') backToBrowsing()
    else location.hash = '#/favourites'
  })

  dom.themeBtn.addEventListener('click', () => {
    const order = ['system', 'light', 'dark']
    const next = order[(order.indexOf(settings.theme) + 1) % order.length]
    settings.theme = next
    saveStore()
    applyTheme(next)
    toast(`Theme: ${THEME_LABELS[next]}`, 1400)
  })

  dom.categoryMore.addEventListener('click', () => {
    const collapsed = dom.categoryChips.dataset.collapsed === 'true'
    dom.categoryChips.dataset.collapsed = String(!collapsed)
    dom.categoryMore.setAttribute('aria-expanded', String(collapsed))
    const total = (state.meta.categories || []).length
    dom.categoryMore.textContent = collapsed ? 'Show fewer' : `Show all ${total}`
  })

  dom.languageSelect.addEventListener('change', () => {
    state.view.language = dom.languageSelect.value || null
    settings.language = state.view.language
    saveStore()
    refreshView()
  })

  dom.providerSelect.addEventListener('change', () => {
    state.view.provider = dom.providerSelect.value || null
    settings.provider = state.view.provider
    saveStore()

    // Pluto TV lives in the US, Rakuten in France. Browsing one while parked on
    // a country it does not serve would just show an empty grid, so follow it.
    const provider = (state.meta.providers || []).find(p => p.id === state.view.provider)
    const presentHere = state.channels.some(c => (c.providers || []).includes(state.view.provider))
    if (provider?.topCountry && !presentHere && state.view.kind === 'country') {
      const target = state.meta.countries.find(c => c.code === provider.topCountry)
      if (target) {
        toast(`${provider.name} is mostly in ${target.name} — switching`, 2600)
        location.hash = `#/country/${provider.topCountry.toLowerCase()}`
        return
      }
    }
    refreshView()
  })

  dom.clearFilters.addEventListener('click', () => {
    state.view.category = null
    state.view.language = null
    state.view.provider = null
    settings.language = null
    settings.provider = null
    saveStore()
    dom.languageSelect.value = ''
    dom.providerSelect.value = ''
    syncChips()
    refreshView()
  })

  dom.countryFilter.addEventListener('input', () => {
    renderCountryList(dom.countryFilter.value)
    syncCountrySelection()
  })

  dom.playerClose.addEventListener('click', () => closePlayer())
  dom.playerBack.addEventListener('click', () => closePlayer())
  dom.playerPrev.addEventListener('click', () => stepChannel(-1))
  dom.playerNext.addEventListener('click', () => stepChannel(1))
  dom.backdrop.addEventListener('mousedown', event => {
    if (event.target === dom.backdrop) closePlayer()
  })

  // Browser / Android back closes the player rather than leaving the site.
  window.addEventListener('popstate', () => {
    if (!dom.backdrop.hidden) closePlayer({ fromHistory: true })
  })
  dom.playerFav.addEventListener('click', () => {
    if (!state.current) return
    dom.playerFav.setAttribute('aria-pressed', String(toggleFavourite(state.current)))
    if (state.view.kind === 'favourites') showFavourites()
  })
  dom.videoRetry.addEventListener('click', () => {
    const next = nextUntried(state.sourceIndex)
    if (next === -1) return
    attempt(next, firstMode(state.current.streams[next]))
  })

  dom.settingsBtn.addEventListener('click', () => openSettings(dom.settingsSheet.hidden))
  dom.settingsClose.addEventListener('click', () => openSettings(false))
  dom.settingsSheet.addEventListener('mousedown', event => {
    if (event.target === dom.settingsSheet) openSettings(false)
  })

  dom.proxyInput.addEventListener('change', () => {
    settings.proxy = dom.proxyInput.value.trim()
    saveStore()
    toast(settings.proxy ? `Proxy set to ${settings.proxy}` : 'Proxy disabled — only CORS-friendly HTTPS streams will play')
  })

  const bindToggle = (input, key, after) => {
    input.addEventListener('change', () => {
      settings[key] = input.checked
      saveStore()
      after?.()
    })
  }
  bindToggle(dom.directFirst, 'directFirst', () => state.current && renderSources())
  bindToggle(dom.showNsfw, 'showNsfw', () => refreshView())
  bindToggle(dom.autoNext, 'autoNext')

  document.addEventListener('keydown', event => {
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)

    if (event.key === 'Escape') {
      if (!dom.settingsSheet.hidden) return openSettings(false)
      if (!dom.backdrop.hidden) return closePlayer()
      if (typing) event.target.blur()
      return
    }
    if (typing) return

    if (event.key === '/') {
      event.preventDefault()
      dom.search.focus()
      dom.search.select()
      return
    }
    if (dom.backdrop.hidden) return

    if (event.key === 'ArrowRight') {
      event.preventDefault()
      stepChannel(1)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      stepChannel(-1)
    } else if (event.key === 'f') {
      const shell = dom.video.parentElement
      if (document.fullscreenElement) document.exitFullscreen()
      else shell.requestFullscreen?.().catch(() => dom.video.webkitEnterFullscreen?.())
    } else if (event.key === 'm') {
      dom.video.muted = !dom.video.muted
      toast(dom.video.muted ? 'Muted' : 'Unmuted', 1200)
    } else if (event.key === 'n') {
      const next = nextUntried(state.sourceIndex)
      if (next !== -1) attempt(next, firstMode(state.current.streams[next]))
    }
  })

  window.addEventListener('hashchange', route)
}

// -------------------------------------------------------------------- init

async function init() {
  applyTheme(settings.theme)
  dom.proxyInput.value = settings.proxy
  dom.directFirst.checked = settings.directFirst
  dom.showNsfw.checked = settings.showNsfw
  dom.autoNext.checked = settings.autoNext
  renderFavCount()

  try {
    state.meta = await getJSON('./data/meta.json')
  } catch {
    dom.viewTitle.textContent = 'Channel data not found'
    dom.viewSub.textContent = ''
    dom.grid.setAttribute('aria-busy', 'false')
    dom.emptyState.hidden = false
    dom.emptyBody.textContent =
      'Run `npm run build` inside web/ to generate ./data from the streams/ playlists.'
    return
  }

  dom.footStats.textContent =
    `${state.meta.totalChannels.toLocaleString()} channels · ` +
    `${state.meta.totalStreams.toLocaleString()} sources · ` +
    `${state.meta.countries.length} countries`
  dom.footGenerated.textContent = `index built ${new Date(state.meta.generatedAt).toLocaleString()}`

  state.view.language =
    (state.meta.languages || []).some(l => l.code === settings.language)
      ? settings.language
      : null
  state.view.provider =
    (state.meta.providers || []).some(p => p.id === settings.provider)
      ? settings.provider
      : null

  renderSidebar()
  bindEvents()
  route()
}

init()
